<?php namespace App\Models; use Illuminate\Database\Eloquent\Model; class StockTransaction extends Model {protected $fillable=['transaction_date','type','reference_no','supplier_id','salesperson_id','warehouse_id','destination','discount','tax','attachment','notes','user_id']; protected $casts=['transaction_date'=>'date']; public function items(){return $this->hasMany(StockTransactionItem::class);} public function supplier(){return $this->belongsTo(Supplier::class);} public function salesperson(){return $this->belongsTo(Salesperson::class);} public function user(){return $this->belongsTo(User::class);}}
